/**
 * Scenario 2: Document Ingestion Under Load
 *
 * 50 virtual users simultaneously upload a ~200 KB PDF (simulates a 10-page document).
 * Each VU uploads 1 file and then polls until status = 'ready' or 'failed'.
 *
 * Pass criteria:
 *   - All files reach status='ready' within 10 minutes
 *   - HTTP upload response: p95 < 5000ms (202 Accepted)
 *   - Processing completion (polling): all within 600s (10 min)
 *
 * Note: This test requires:
 *   - A valid DASHBOARD_TOKEN
 *   - A CHATBOT_UUID whose chatbot accepts documents
 *   - The load-tests/fixtures/sample.pdf file (generated by setup.sh)
 */

import http from 'k6/http';
import { check, sleep } from 'k6';
import { Trend, Counter } from 'k6/metrics';
import { open } from 'k6/experimental/fs';
import {
  API_BASE,
  CHATBOT_UUID,
  DASHBOARD_TOKEN,
  dashboardHeaders,
} from '../k6.config.js';

const uploadDuration    = new Trend('upload_duration_ms',    true);
const processDuration   = new Trend('process_duration_ms',   true);
const processedCount    = new Counter('documents_processed');
const failedCount       = new Counter('documents_failed');
const timedOutCount     = new Counter('documents_timed_out');

export const options = {
  scenarios: {
    document_ingestion: {
      executor:    'per-vu-iterations',
      vus:         50,
      iterations:  1,
      maxDuration: '15m',
    },
  },
  thresholds: {
    upload_duration_ms:  ['p(95)<5000'],
    documents_failed:    ['count<3'],    // tolerate < 3 failures in 50 uploads
    documents_timed_out: ['count<5'],    // all should finish within 10 min
    http_req_failed:     ['rate<0.02'],
  },
};

// k6 experimental/fs: open the sample PDF once per VU
let samplePdf;

export function setup() {
  // Returns the file path; actual open is per-VU
  return { pdfPath: './load-tests/fixtures/sample.pdf' };
}

export default function (data) {
  if (!CHATBOT_UUID || !DASHBOARD_TOKEN) {
    console.error('CHATBOT_UUID and DASHBOARD_TOKEN env vars are required');
    return;
  }

  const uploadStart = Date.now();

  // ── Upload the PDF ────────────────────────────────────────────────────────
  // k6 uses a FormData-equivalent via the multipart/form-data body builder.
  // We use a binary file read for realistic upload sizes.
  const formData = {
    file: http.file(
      open('./load-tests/fixtures/sample.pdf', 'b'),
      `test-doc-vu${__VU}.pdf`,
      'application/pdf',
    ),
    title: `Load Test Document VU ${__VU}`,
  };

  const uploadRes = http.post(
    `${API_BASE}/chatbots/${CHATBOT_UUID}/documents`,
    formData,
    {
      headers: { Authorization: `Bearer ${DASHBOARD_TOKEN}` },
      tags:    { name: 'upload_doc' },
      timeout: '30s',
    },
  );

  uploadDuration.add(Date.now() - uploadStart);

  const uploadOk = check(uploadRes, {
    'upload accepted 201/202': (r) => r.status === 201 || r.status === 202,
  });

  if (!uploadOk) {
    failedCount.add(1);
    console.error(`VU ${__VU}: upload failed with status ${uploadRes.status}: ${uploadRes.body}`);
    return;
  }

  const docId = JSON.parse(uploadRes.body).data?.id;
  if (!docId) {
    failedCount.add(1);
    return;
  }

  // ── Poll until processing completes ──────────────────────────────────────
  const processStart = Date.now();
  const maxWaitMs    = 10 * 60 * 1000; // 10 minutes
  const pollInterval = 5;              // poll every 5 seconds

  while (Date.now() - processStart < maxWaitMs) {
    sleep(pollInterval);

    const pollRes = http.get(
      `${API_BASE}/chatbots/${CHATBOT_UUID}/documents`,
      {
        headers: dashboardHeaders(),
        tags:    { name: 'poll_doc_status' },
      },
    );

    if (pollRes.status !== 200) continue;

    const docs = JSON.parse(pollRes.body).data ?? [];
    const doc  = docs.find((d) => d.id === docId);

    if (!doc) continue;

    if (doc.status === 'ready') {
      const elapsed = Date.now() - processStart;
      processDuration.add(elapsed);
      processedCount.add(1);
      console.log(`VU ${__VU}: document ready in ${(elapsed / 1000).toFixed(1)}s (${doc.chunk_count ?? '?'} chunks)`);
      return;
    }

    if (doc.status === 'failed') {
      failedCount.add(1);
      console.error(`VU ${__VU}: document processing failed: ${doc.error_message}`);
      return;
    }
  }

  timedOutCount.add(1);
  console.warn(`VU ${__VU}: document processing timed out after 10 minutes`);
}
